-- The schema the 59 SeaORM migrations built (m20220101_000001 to m20261031_000059), as one
-- baseline (CRM-D24, CRM-T229). Generated by `pg_dump --schema-only --no-owner --no-privileges`
-- from a database those migrations alone had made, less the dump's `SET` lines, its search-path
-- reset, its comments and the extensions' comments, and with each `IN (...)` check on a varchar
-- column written as the migration wrote it: the dump's form of one parses to another expression,
-- which `tests/requests/schema.rs` tells apart. A database the history migrated records this
-- as applied and runs nothing (`src/schema.rs`); a new one runs it. It is never edited: sqlx
-- refuses a database whose applied migration's checksum has changed. Change the schema with a
-- new migration after it.

CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;

CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA public;

CREATE FUNCTION public.audit_logs_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'audit_logs is append-only'; END IF; IF OLD.hash IS NULL AND NEW.hash IS NOT NULL AND (OLD.id, OLD.entity, OLD.entity_pid, OLD.action, OLD.actor, OLD.snapshot, OLD.prev_hash, OLD.created_at) IS NOT DISTINCT FROM (NEW.id, NEW.entity, NEW.entity_pid, NEW.action, NEW.actor, NEW.snapshot, NEW.prev_hash, NEW.created_at) THEN RETURN NEW; END IF; RAISE EXCEPTION 'audit_logs is append-only'; END; $$;

CREATE FUNCTION public.crm_consent_profile_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
     BEGIN
       RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
     END; $$;

CREATE FUNCTION public.crm_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN NEW.updated_at := now(); END IF; RETURN NEW; END; $$;

CREATE FUNCTION public.immutable_unaccent(text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $_$ SELECT public.unaccent('public.unaccent'::regdictionary, $1) $_$;

CREATE FUNCTION public.search_ngrams(t text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE
    AS $$ DECLARE extra text := ''; run text; n int; BEGIN FOR run IN SELECT (regexp_matches(t, E'[\u0E00-\u0E7F\u0E80-\u0EFF\u1000-\u109F\u1780-\u17FF\u3040-\u309F\u30A0-\u30FF\u31F0-\u31FF\u3400-\u4DBF\u4E00-\u9FFF\uAC00-\uD7AF\uF900-\uFAFF\uFF66-\uFF9F\U00020000-\U000323AF]+', 'g'))[1] LOOP n := char_length(run); FOR i IN 1..n LOOP extra := extra || ' ' || substr(run, i, 1); IF i < n THEN extra := extra || ' ' || substr(run, i, 2); END IF; END LOOP; END LOOP; RETURN t || extra; END $$;

